TECH_SPEC_HTML = '<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>SC3 DocAudit — Especificação Técnica & Metodologia Científica</title>\n    <meta name="description" content="Documentação técnica profissional, formalização matemática, algoritmos de visão computacional, calibração estocástica e fundamentação pericial forense (CPP).">\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&display=swap" rel="stylesheet">\n    <style>\n        :root {\n            --primary: #1E6B52;\n            --primary-dark: #134E39;\n            --primary-light: #257C60;\n            --bg-light: #F4F7F6;\n            --card-bg: #FFFFFF;\n            --border-color: #DCE3E8;\n            --border-focus: #1E6B52;\n            --text-dark: #1A1A1A;\n            --text-muted: #555555;\n            --text-subtle: #718096;\n            --success: #137333;\n            --success-bg: #E6F4EA;\n            --warning: #D97706;\n            --warning-bg: #FEF3C7;\n            --danger: #DC2626;\n            --danger-bg: #FEE2E2;\n            --font-main: \'Plus Jakarta Sans\', -apple-system, BlinkMacSystemFont, sans-serif;\n            --font-mono: \'JetBrains Mono\', monospace;\n        }\n\n        * { box-sizing: border-box; margin: 0; padding: 0; }\n        body {\n            font-family: var(--font-main);\n            background-color: var(--bg-light);\n            color: var(--text-dark);\n            line-height: 1.6;\n            padding: 16px;\n        }\n\n        .container {\n            max-width: 1200px;\n            margin: 0 auto;\n        }\n\n        /* Institutional Header (Identical to Web App) */\n        .top-header {\n            background: linear-gradient(135deg, var(--primary-dark) 0%, var(--primary) 60%, var(--primary-light) 100%);\n            border-radius: 12px;\n            padding: 20px 26px;\n            color: #FFFFFF;\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            gap: 16px;\n            flex-wrap: wrap;\n            box-shadow: 0 4px 16px rgba(19, 78, 57, 0.22);\n            margin-bottom: 24px;\n        }\n\n        .header-title-area h1 {\n            font-size: 24px;\n            font-weight: 800;\n            letter-spacing: 0.3px;\n        }\n\n        .header-title-area p {\n            font-size: 13.5px;\n            opacity: 0.95;\n            margin-top: 4px;\n        }\n\n        .header-actions {\n            display: flex;\n            gap: 10px;\n            align-items: center;\n            flex-wrap: wrap;\n        }\n\n        .btn-header {\n            background: rgba(255, 255, 255, 0.18);\n            border: 1px solid rgba(255, 255, 255, 0.4);\n            color: #FFFFFF;\n            text-decoration: none;\n            padding: 7px 14px;\n            border-radius: 6px;\n            font-weight: 700;\n            font-size: 13px;\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            cursor: pointer;\n            transition: all 0.2s;\n        }\n\n        .btn-header:hover {\n            background: rgba(255, 255, 255, 0.3);\n        }\n\n        .lang-switch-btn {\n            background: #FFFFFF;\n            color: var(--primary-dark);\n            border: none;\n            font-weight: 800;\n            padding: 7px 14px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-size: 13px;\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            box-shadow: 0 2px 6px rgba(0,0,0,0.1);\n        }\n\n        /* Summary Badges */\n        .kpi-row {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n            gap: 14px;\n            margin-bottom: 24px;\n        }\n\n        .kpi-card {\n            background: var(--card-bg);\n            border: 1px solid var(--border-color);\n            border-radius: 10px;\n            padding: 16px;\n            box-shadow: 0 2px 6px rgba(0,0,0,0.03);\n        }\n\n        .kpi-label {\n            font-size: 11.5px;\n            font-weight: 700;\n            color: var(--text-muted);\n            text-transform: uppercase;\n            letter-spacing: 0.5px;\n        }\n\n        .kpi-val {\n            font-size: 18px;\n            font-weight: 800;\n            color: var(--primary-dark);\n            margin-top: 4px;\n        }\n\n        .kpi-sub {\n            font-size: 12px;\n            color: var(--text-subtle);\n            margin-top: 2px;\n        }\n\n        /* Technical Sections */\n        .section-card {\n            background: var(--card-bg);\n            border: 1px solid var(--border-color);\n            border-radius: 12px;\n            padding: 24px;\n            margin-bottom: 24px;\n            box-shadow: 0 2px 8px rgba(0,0,0,0.03);\n        }\n\n        .section-header {\n            display: flex;\n            align-items: center;\n            gap: 12px;\n            border-bottom: 1.5px solid var(--border-color);\n            padding-bottom: 12px;\n            margin-bottom: 18px;\n        }\n\n        .section-number {\n            background: var(--primary);\n            color: #FFFFFF;\n            width: 32px;\n            height: 32px;\n            border-radius: 6px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-weight: 800;\n            font-size: 14px;\n            flex-shrink: 0;\n        }\n\n        .section-title h2 {\n            font-size: 18px;\n            font-weight: 800;\n            color: var(--primary-dark);\n        }\n\n        .section-title p {\n            font-size: 12.5px;\n            color: var(--text-muted);\n        }\n\n        h3 {\n            font-size: 15px;\n            font-weight: 700;\n            color: var(--primary-dark);\n            margin: 16px 0 8px;\n        }\n\n        p {\n            font-size: 14px;\n            color: var(--text-dark);\n            margin-bottom: 12px;\n        }\n\n        ul {\n            margin-left: 20px;\n            margin-bottom: 16px;\n        }\n\n        li {\n            font-size: 13.5px;\n            color: var(--text-dark);\n            margin-bottom: 6px;\n        }\n\n        /* Code & Mathematical Formulas */\n        .math-box {\n            background: #F8FAFC;\n            border: 1px solid var(--border-color);\n            border-left: 4px solid var(--primary);\n            border-radius: 6px;\n            padding: 14px 18px;\n            font-family: var(--font-mono);\n            font-size: 13.5px;\n            color: var(--primary-dark);\n            margin: 14px 0;\n            overflow-x: auto;\n        }\n\n        .code-box {\n            background: #1E293B;\n            border-radius: 8px;\n            padding: 14px 18px;\n            font-family: var(--font-mono);\n            font-size: 12.5px;\n            color: #38BDF8;\n            overflow-x: auto;\n            margin: 12px 0;\n            line-height: 1.5;\n        }\n\n        .grid-2 {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));\n            gap: 18px;\n            margin: 14px 0;\n        }\n\n        /* Interactive Simulator Panel */\n        .sim-card {\n            background: #F0FDF4;\n            border: 1.5px solid #86EFAC;\n            border-radius: 10px;\n            padding: 20px;\n            margin: 18px 0;\n        }\n\n        .sim-title {\n            font-size: 15px;\n            font-weight: 800;\n            color: var(--primary-dark);\n            margin-bottom: 12px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n\n        .sim-input-row {\n            display: grid;\n            grid-template-columns: 1fr auto;\n            align-items: center;\n            gap: 12px;\n            margin-bottom: 10px;\n        }\n\n        .sim-slider {\n            width: 100%;\n            height: 6px;\n            border-radius: 3px;\n            background: #CBD5E1;\n            outline: none;\n        }\n\n        .sim-score-badge {\n            font-family: var(--font-mono);\n            font-size: 13px;\n            font-weight: 700;\n            padding: 4px 10px;\n            border-radius: 6px;\n            background: #FFFFFF;\n            border: 1px solid var(--border-color);\n        }\n\n        .sim-result-box {\n            background: #FFFFFF;\n            border: 1.5px solid var(--primary);\n            border-radius: 8px;\n            padding: 12px 16px;\n            margin-top: 14px;\n            font-family: var(--font-mono);\n            font-size: 13px;\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            flex-wrap: wrap;\n            gap: 8px;\n        }\n\n        /* Live Merkle Simulator */\n        .merkle-leaf-input {\n            width: 100%;\n            padding: 8px 10px;\n            border-radius: 6px;\n            border: 1.5px solid var(--border-color);\n            font-family: var(--font-mono);\n            font-size: 12.5px;\n            margin-bottom: 8px;\n        }\n\n        .merkle-leaf-input:focus {\n            outline: none;\n            border-color: var(--primary);\n        }\n\n        .merkle-hash-display {\n            background: #1E293B;\n            color: #4ADE80;\n            font-family: var(--font-mono);\n            font-size: 12px;\n            padding: 10px 14px;\n            border-radius: 6px;\n            word-break: break-all;\n            margin-top: 6px;\n        }\n\n        /* Roadmap Table */\n        .roadmap-table {\n            width: 100%;\n            border-collapse: collapse;\n            margin-top: 12px;\n            font-size: 13px;\n        }\n\n        .roadmap-table th, .roadmap-table td {\n            border: 1px solid var(--border-color);\n            padding: 10px 14px;\n            text-align: left;\n        }\n\n        .roadmap-table th {\n            background: #F8FAFC;\n            font-weight: 700;\n            color: var(--primary-dark);\n        }\n\n        .status-badge {\n            display: inline-block;\n            padding: 3px 8px;\n            border-radius: 4px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n\n        .status-done { background: var(--success-bg); color: var(--success); }\n        .status-prog { background: var(--warning-bg); color: var(--warning); }\n        .status-plan { background: #F1F5F9; color: var(--text-muted); }\n\n        footer {\n            border-top: 1px solid var(--border-color);\n            padding: 24px 0 36px;\n            text-align: center;\n            font-size: 13px;\n            color: var(--text-muted);\n            margin-top: 36px;\n        }\n\n        footer a { color: var(--primary); text-decoration: none; font-weight: 600; }\n        footer a:hover { text-decoration: underline; }\n    </style>\n</head>\n<body>\n\n<div class="container">\n\n    <!-- Top Institutional Header -->\n    <header class="top-header">\n        <div class="header-title-area">\n            <h1>🛡️ SC3 DocAudit &bull; Documentação Técnica</h1>\n            <p>Especificação Algorítmica, Calibração Estocástica e Metodologia Forense (CPP)</p>\n        </div>\n        <div class="header-actions">\n            <button class="lang-switch-btn" onclick="toggleLanguage()" id="langBtn">\n                🌐 EN (English)\n            </button>\n            <a href="/" class="btn-header">\n                ⬅️ <span class="txt-pt">Voltar ao Painel</span><span class="txt-en" style="display:none;">Back to App</span>\n            </a>\n        </div>\n    </header>\n\n    <!-- Metrics Summary -->\n    <div class="kpi-row">\n        <div class="kpi-card">\n            <div class="kpi-label"><span class="txt-pt">Complexidade de Colisão</span><span class="txt-en" style="display:none;">Collision Resistance</span></div>\n            <div class="kpi-val">2²⁵⁶ ≈ 1.15 × 10⁷⁷</div>\n            <div class="kpi-sub"><span class="txt-pt">Função Criptográfica SHA-256</span><span class="txt-en" style="display:none;">SHA-256 One-Way Digest</span></div>\n        </div>\n        <div class="kpi-card">\n            <div class="kpi-label"><span class="txt-pt">Limiar Anti-Alucinação</span><span class="txt-en" style="display:none;">Anti-Hallucination Threshold</span></div>\n            <div class="kpi-val">τ = 0.35</div>\n            <div class="kpi-sub"><span class="txt-pt">Score composto &lt; 0.35 &rarr; valor null</span><span class="txt-en" style="display:none;">Composite score &lt; 0.35 &rarr; null value</span></div>\n        </div>\n        <div class="kpi-card">\n            <div class="kpi-label"><span class="txt-pt">Conformidade Pericial</span><span class="txt-en" style="display:none;">Forensic Standard</span></div>\n            <div class="kpi-val"><span class="txt-pt">Arts. 158-A a 158-F</span><span class="txt-en" style="display:none;">Arts. 158-A to 158-F</span></div>\n            <div class="kpi-sub"><span class="txt-pt">Código de Processo Penal Brasileiro</span><span class="txt-en" style="display:none;">Brazilian Criminal Procedure Code</span></div>\n        </div>\n        <div class="kpi-card">\n            <div class="kpi-label"><span class="txt-pt">Suíte de Validação</span><span class="txt-en" style="display:none;">Test Validation Suite</span></div>\n            <div class="kpi-val">17 / 17 Testes</div>\n            <div class="kpi-sub"><span class="txt-pt">100% Passing (Adversarial Robustness)</span><span class="txt-en" style="display:none;">100% Passing (Adversarial Robustness)</span></div>\n        </div>\n    </div>\n\n    <!-- Section 1: Architecture -->\n    <div class="section-card">\n        <div class="section-header">\n            <div class="section-number">1</div>\n            <div class="section-title">\n                <h2><span class="txt-pt">Arquitetura Centrada na Ocorrência (Occurrence-First 1:N)</span><span class="txt-en" style="display:none;">Occurrence-First Relational Architecture (1:N)</span></h2>\n                <p><span class="txt-pt">Modelo de dados discreto e integridade relacional sem rede</span><span class="txt-en" style="display:none;">Discrete data modeling & zero-network relational integrity</span></p>\n            </div>\n        </div>\n        \n        <p class="txt-pt">\n            Em fiscalizações ambientais na Amazônia, a unidade fundamental de prova não é um documento isolado, mas a <strong>Ocorrência Fiscalizatória ($O$)</strong>. O modelo relacional estrutura cada operação como uma tupla contendo $n$ peças físicas e $m$ evidências multimodais coletadas em campo:\n        </p>\n        <p class="txt-en" style="display:none;">\n            In remote environmental inspections, the fundamental unit of evidentiary value is not an isolated sheet of paper, but the <strong>Enforcement Occurrence ($O$)</strong>. The relational model formalizes each inspection as a discrete tuple composed of $n$ physical documents and $m$ multimodal sensor assets:\n        </p>\n\n        <div class="math-box">\n            <span class="txt-pt">Ocorrência = ( ID_occ, { D₁, D₂, ..., Dₙ }, Evidências_Fotos, Áudios_Voz, Logs_GPS, Raiz_Merkle )</span>\n            <span class="txt-en" style="display:none;">Occurrence = ( ID_occ, { D₁, D₂, ..., Dₙ }, Photo_Assets, Voice_Dictations, GPS_Logs, Merkle_Root )</span>\n        </div>\n\n        <p class="txt-pt">\n            <strong>Propriedades Formais da Camada de Persistência:</strong>\n        </p>\n        <p class="txt-en" style="display:none;">\n            <strong>Formal Properties of the Persistence Layer:</strong>\n        </p>\n        <ul>\n            <li><span class="txt-pt"><strong>Isolamento ACID Local</strong>: Transações atômicas embarcadas em SQLite local (<code>occurrences.db</code>) sem dependência de sockets de rede ou servidores em nuvem.</span><span class="txt-en" style="display:none;"><strong>Local ACID Isolation</strong>: Atomic, isolated transactions executed on embedded SQLite without network sockets or cloud servers.</span></li>\n            <li><span class="txt-pt"><strong>Indexação de Texto Pleno (FTS)</strong>: Busca sub-milissegundo por número de auto, CPF/CNPJ, código CAR e matrícula de agente ambiental.</span><span class="txt-en" style="display:none;"><strong>Full-Text Indexing (FTS)</strong>: Sub-millisecond lookup across document identifiers, tax IDs, CAR polygon codes, and officer registrations.</span></li>\n        </ul>\n    </div>\n\n    <!-- Section 2: Vision Pipeline -->\n    <div class="section-card">\n        <div class="section-header">\n            <div class="section-number">2</div>\n            <div class="section-title">\n                <h2><span class="txt-pt">Processamento Digital de Imagens (PDI) & Retificação Geométrica</span><span class="txt-en" style="display:none;">Digital Image Processing (DIP) & Geometric Rectification</span></h2>\n                <p><span class="txt-pt">Pipeline determinístico para tratamento de documentos físicos degradados</span><span class="txt-en" style="display:none;">Deterministic pipeline engineered for degraded field notices</span></p>\n            </div>\n        </div>\n\n        <p class="txt-pt">\n            Documentos fotografados sob a copa da floresta sofrem com rotações de plano (θ), sombras oclusivas e traços fracos de papel carbono. O módulo <code>sc3_docaudit/core/image_preprocessing.py</code> executa uma esteira em quatro etapas:\n        </p>\n        <p class="txt-en" style="display:none;">\n            Notices photographed in rainforest conditions suffer from planar rotation (θ), tree canopy cast shadows, and weathered carbon copies. The <code>image_preprocessing.py</code> module applies a 4-stage deterministic pipeline:\n        </p>\n\n        <div class="grid-2">\n            <div>\n                <h3><span class="txt-pt">1. Retificação de Inclinação (Deskew)</span><span class="txt-en" style="display:none;">1. Orientation & Deskewing</span></h3>\n                <p class="txt-pt">Calcula os momentos estatísticos centrais μ₂₀, μ₀₂, μ₁₁ do contorno de maior área via <code>cv2.minAreaRect</code> para determinar o ângulo principal de orientação θ. Aplica-se a matriz de transformação afim de rotação M(θ) para restaurar o alinhamento horizontal dos caracteres antes da extração OCR.</p>\n                <p class="txt-en" style="display:none;">Calculates central geometric moments μ₂₀, μ₀₂, μ₁₁ of the largest connected contour via <code>cv2.minAreaRect</code> to estimate principal angle θ. Applies an affine transformation matrix M(θ) to enforce horizontal baseline alignment prior to OCR parsing.</p>\n            </div>\n            <div>\n                <h3><span class="txt-pt">2. Equalização Local de Contraste (CLAHE)</span><span class="txt-en" style="display:none;">2. Local Contrast Equalization (CLAHE)</span></h3>\n                <p class="txt-pt">Diferente da equalização global que queima áreas claras, o CLAHE atua sobre sub-blocos discretos de 8 × 8 pixels com limite de corte (Clip Limit) β = 2.0, redistribuindo o gradiente de luminância sem amplificar o ruído térmico do sensor.</p>\n                <p class="txt-en" style="display:none;">Unlike global histogram equalization which saturates highlights, CLAHE divides the grayscale image into contextual 8 × 8 tiles with a clipping threshold β = 2.0, evening out lighting without over-amplifying background sensor noise.</p>\n            </div>\n        </div>\n\n        <div class="code-box">\n# Expressão de Binarização Gaussiana Adaptativa:\n# T(x, y) = [ (1/W) * sum(G(i, j) * I(x+i, y+j)) ] - C\nenhanced = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8,8)).apply(denoised)\nbinary = cv2.adaptiveThreshold(enhanced, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY, 11, 2)\n        </div>\n    </div>\n\n    <!-- Section 3: Neural OCR & Semantic Parser -->\n    <div class="section-card">\n        <div class="section-header">\n            <div class="section-number">3</div>\n            <div class="section-title">\n                <h2><span class="txt-pt">OCR Neural & Parser Semântico Baseado em Autômatos</span><span class="txt-en" style="display:none;">Neural OCR & Automata-Based Semantic Parsing</span></h2>\n                <p><span class="txt-pt">Extração agnóstica a layouts e modelagem determinística de entidades</span><span class="txt-en" style="display:none;">Layout-agnostic extraction and deterministic entity modeling</span></p>\n            </div>\n        </div>\n\n        <p class="txt-pt">\n            O reconhecimento de caracteres utiliza redes neurais convolucionais-recorrentes (CRNN) com função de perda <em>Connectionist Temporal Classification (CTC)</em>, gerando caixas delimitadoras e probabilidades bayesianas P_OCR ∈ [0.0, 1.0].\n        </p>\n        <p class="txt-en" style="display:none;">\n            Character recognition is powered by a Deep Convolutional Recurrent Neural Network (CRNN) with Connectionist Temporal Classification (CTC) loss, producing bounding boxes with native Bayesian probabilities P_OCR ∈ [0.0, 1.0].\n        </p>\n        <p class="txt-pt">\n            Para estruturar o texto em campos jurídicos conforme o <code>schema.md</code>, o motor aplica <strong>Autômatos Finitos Determinísticos (DFA)</strong> com âncoras léxicas estritas para identificar autuados, CPFs/CNPJs, códigos do CAR, enquadramentos legais (<em>Lei Federal nº 9.605/1998</em> e <em>Decreto Federal nº 6.514/2008</em>) e valores de multa em reais.\n        </p>\n        <p class="txt-en" style="display:none;">\n            To map raw textual sequences into normalized legal entities adhering to <code>schema.md</code>, the engine applies <strong>Deterministic Finite Automata (DFA)</strong> anchored to legal tokens, extracting parties, tax IDs, CAR polygon codes, and infraction articles.\n        </p>\n    </div>\n\n    <!-- Section 4: Confidence Calibration & Anti-Hallucination -->\n    <div class="section-card">\n        <div class="section-header">\n            <div class="section-number">4</div>\n            <div class="section-title">\n                <h2><span class="txt-pt">Modelo de Calibração de Confiança & Política Anti-Alucinação</span><span class="txt-en" style="display:none;">Confidence Calibration Model & Anti-Hallucination Threshold</span></h2>\n                <p><span class="txt-pt">Formulação matemática ponderada e descarte determinístico de incerteza</span><span class="txt-en" style="display:none;">Weighted multi-factor mathematical formulation and deterministic cutoff</span></p>\n            </div>\n        </div>\n\n        <p class="txt-pt">\n            A pontuação de incerteza do SC3 DocAudit é governada por uma função linear convexa delimitada no intervalo [0.0, 1.0]:\n        </p>\n        <p class="txt-en" style="display:none;">\n            The uncertainty calibration score is computed via a bounded convex linear combination in [0.0, 1.0]:\n        </p>\n\n        <div class="math-box">\n            <span class="txt-pt">Confiança(x) = min( 1.0, max( 0.0, 0.45 · P_OCR + 0.35 · V_Sintaxe + 0.20 · A_Espacial ) )</span>\n            <span class="txt-en" style="display:none;">Confidence(x) = min( 1.0, max( 0.0, 0.45 · P_OCR + 0.35 · V_Syntax + 0.20 · A_Spatial ) )</span>\n        </div>\n\n        <p class="txt-pt">\n            Onde os coeficientes foram parametrizados empiricamente: $w_1 = 0.45$ (evidência óptica neural), $w_2 = 0.35$ (validação de formato sintático oficial), e $w_3 = 0.20$ (pertencimento ao retângulo envolvente da Amazônia Legal).\n        </p>\n        <p class="txt-en" style="display:none;">\n            Where weights are empirically calibrated: $w_1 = 0.45$ (neural optical score), $w_2 = 0.35$ (syntactic regex mask), and $w_3 = 0.20$ (geographical consistency inside the Legal Amazon bounding box).\n        </p>\n\n        <!-- Interactive Simulator -->\n        <div class="sim-card">\n            <div class="sim-title">\n                <span>🎛️</span>\n                <span class="txt-pt">Simulador de Calibração & Limiar Anti-Alucinação (τ = 0.35)</span>\n                <span class="txt-en" style="display:none;">Interactive Confidence & Anti-Hallucination Simulator (τ = 0.35)</span>\n            </div>\n            \n            <div class="sim-input-row">\n                <label style="font-size:13px; font-weight:600;"><span class="txt-pt">Probabilidade OCR (P_OCR - Peso 45%)</span><span class="txt-en" style="display:none;">OCR Bayesian Probability (45% Weight)</span></label>\n                <input type="range" min="0" max="100" value="70" class="sim-slider" id="sim_ocr" oninput="runSim()">\n                <span class="sim-score-badge" id="val_ocr">0.70</span>\n            </div>\n\n            <div class="sim-input-row">\n                <label style="font-size:13px; font-weight:600;"><span class="txt-pt">Validação Sintática / Máscara (V_Syntax - Peso 35%)</span><span class="txt-en" style="display:none;">Syntactic Mask Verification (35% Weight)</span></label>\n                <input type="range" min="0" max="100" value="90" class="sim-slider" id="sim_syn" oninput="runSim()">\n                <span class="sim-score-badge" id="val_syn">0.90</span>\n            </div>\n\n            <div class="sim-input-row">\n                <label style="font-size:13px; font-weight:600;"><span class="txt-pt">Consistência Territorial Amazônica (A_Spatial - Peso 20%)</span><span class="txt-en" style="display:none;">Spatial Geodesic Consistency (20% Weight)</span></label>\n                <input type="range" min="0" max="100" value="85" class="sim-slider" id="sim_spa" oninput="runSim()">\n                <span class="sim-score-badge" id="val_spa">0.85</span>\n            </div>\n\n            <div class="sim-result-box" id="simResultBox">\n                <div>\n                    <strong>Score Composto: <span id="res_score">0.800</span></strong>\n                </div>\n                <div>\n                    <span id="res_tag" class="status-badge status-done">EXTRAÇÃO CONFIÁVEL</span>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- Section 5: Cryptography & Forensic Proofs -->\n    <div class="section-card">\n        <div class="section-header">\n            <div class="section-number">5</div>\n            <div class="section-title">\n                <h2><span class="txt-pt">Cadeia de Custódia Criptográfica & Validade Forense (CPP)</span><span class="txt-en" style="display:none;">Cryptographic Chain of Custody & Judicial Admissibility (CPP)</span></h2>\n                <p><span class="txt-pt">Fundamentação pericial e lacre matemático via Árvore de Merkle SHA-256</span><span class="txt-en" style="display:none;">Forensic verification & mathematical seal via SHA-256 Merkle Trees</span></p>\n            </div>\n        </div>\n\n        <p class="txt-pt">\n            O <strong>Protocolo SC3</strong> implementa o "Lacre Matemático" em conformidade estrita com os <strong>Arts. 158-A a 158-F do Código de Processo Penal Brasileiro</strong> (Lei nº 13.964/2019 - Pacote Anticrime). Ele assegura a <em>"mesmidade da prova"</em> perante os Tribunais:\n        </p>\n        <p class="txt-en" style="display:none;">\n            The <strong>SC3 Protocol</strong> creates an unalterable mathematical seal adhering strictly to <strong>Articles 158-A through 158-F of the Brazilian Criminal Procedure Code</strong> (Law 13,964/2019). It proves the exact continuity and integrity of digital evidence:\n        </p>\n\n        <div class="grid-2">\n            <div>\n                <h3><span class="txt-pt">Propriedades Criptográficas do SHA-256</span><span class="txt-en" style="display:none;">Cryptographic Properties of SHA-256</span></h3>\n                <ul>\n                    <li><span class="txt-pt"><strong>Resistência à Pré-Imagem</strong>: Dado um hash $h$, é computacionalmente inviável encontrar $m$ tal que $H(m) = h$ ($O(2^{256})$).</span><span class="txt-en" style="display:none;"><strong>Pre-image Resistance</strong>: Computationally infeasible to reverse a digest $h$ back to input $m$ ($O(2^{256})$).</span></li>\n                    <li><span class="txt-pt"><strong>Resistência à Colisão</strong>: Inviável encontrar dois arquivos distintos $m_1 \\neq m_2$ com $H(m_1) = H(m_2)$ ($O(2^{128})$ operações pelo Paradoxo do Aniversário).</span><span class="txt-en" style="display:none;"><strong>Collision Resistance</strong>: Infeasible to find $m_1 \\neq m_2$ yielding $H(m_1) = H(m_2)$ ($O(2^{128})$ operations).</span></li>\n                    <li><span class="txt-pt"><strong>Efeito Avalanche</strong>: A alteração de um único bit em uma coordenada ou número de CPF altera irreversivelmente 50% dos bits do Hash Raiz.</span><span class="txt-en" style="display:none;"><strong>Strict Avalanche Effect</strong>: Flipping a single bit in a coordinate or tax ID changes over 50% of the Root Hash bits.</span></li>\n                </ul>\n            </div>\n            <div>\n                <h3><span class="txt-pt">Verificação Independente pelo Tribunal</span><span class="txt-en" style="display:none;">Independent Judicial Terminal Audit</span></h3>\n                <p class="txt-pt">O Perito Judicial ou Promotor pode auditar o arquivo <code>.sc3</code> diretamente no terminal sem softwares proprietários:</p>\n                <p class="txt-en" style="display:none;">Judges, prosecutors, and forensic experts can audit `.sc3` files directly via native terminal binaries:</p>\n                <div class="code-box">\n# Linux / macOS:\nsha256sum Dossie_OC-2026-ALT-01.sc3\n\n# Windows (PowerShell):\ncertutil -hashfile Dossie_OC-2026-ALT-01.sc3 SHA256\n                </div>\n            </div>\n        </div>\n\n        <!-- Live Merkle Tree Simulator -->\n        <div class="sim-card">\n            <div class="sim-title">\n                <span>🌳</span>\n                <span class="txt-pt">Calculadora Forense de Árvore de Merkle (Tempo Real no Navegador)</span>\n                <span class="txt-en" style="display:none;">Live Binary Merkle Tree Calculator (Client-Side SHA-256)</span>\n            </div>\n            <p style="font-size: 13px; color: var(--text-muted);">\n                <span class="txt-pt">Edite as folhas de evidência para observar o cálculo determinístico do Hash Raiz:</span>\n                <span class="txt-en" style="display:none;">Edit leaf evidence assets below to observe real-time Root Hash calculation:</span>\n            </p>\n\n            <div class="grid-2">\n                <div>\n                    <label style="font-size:12px; font-weight:700;"><span class="txt-pt">Folha 1: Auto de Infração Físico</span><span class="txt-en" style="display:none;">Leaf 1: Physical Infraction Notice</span></label>\n                    <input type="text" id="m_leaf1" class="merkle-leaf-input" value="AUTO_INFRACAO_1049_NOVO_PROGRESSO_PA" oninput="computeMerkle()">\n                </div>\n                <div>\n                    <label style="font-size:12px; font-weight:700;"><span class="txt-pt">Folha 2: Extrato JSON Extraído</span><span class="txt-en" style="display:none;">Leaf 2: Structured JSON Extraction</span></label>\n                    <input type="text" id="m_leaf2" class="merkle-leaf-input" value="AREA_HA:145.2;VALOR_MULTA:350000;CAR:PA-1500602" oninput="computeMerkle()">\n                </div>\n                <div>\n                    <label style="font-size:12px; font-weight:700;"><span class="txt-pt">Folha 3: Foto Georreferenciada</span><span class="txt-en" style="display:none;">Leaf 3: GPS Photo Metadata</span></label>\n                    <input type="text" id="m_leaf3" class="merkle-leaf-input" value="LAT:-07.1245;LON:-55.4312;TIMESTAMP:2026-09-15T14:30:00Z" oninput="computeMerkle()">\n                </div>\n                <div>\n                    <label style="font-size:12px; font-weight:700;"><span class="txt-pt">Folha 4: Gravação de Voz do Fiscal</span><span class="txt-en" style="display:none;">Leaf 4: Officer Voice Dictation</span></label>\n                    <input type="text" id="m_leaf4" class="merkle-leaf-input" value="AUDIO_NOTE:Desmatamento recente constatado na coordenada 07 Sul" oninput="computeMerkle()">\n                </div>\n            </div>\n\n            <div style="margin-top: 10px;">\n                <label style="font-size:12px; font-weight:700; color: var(--primary-dark);"><span class="txt-pt">Raiz de Merkle (Selo Forense SC3):</span><span class="txt-en" style="display:none;">Merkle Root Hash (SC3 Forensic Seal):</span></label>\n                <div id="m_root" class="merkle-hash-display">Calculando...</div>\n            </div>\n        </div>\n    </div>\n\n    <!-- Section 6: Roadmap -->\n    <div class="section-card">\n        <div class="section-header">\n            <div class="section-number">6</div>\n            <div class="section-title">\n                <h2><span class="txt-pt">Checklist de Desenvolvimento & Roadmap Técnico</span><span class="txt-en" style="display:none;">Development Checklist & Engineering Roadmap</span></h2>\n                <p><span class="txt-pt">Cronograma de evolução tecnológica e governança aberta</span><span class="txt-en" style="display:none;">Timeline of technological milestones and open-source roadmap</span></p>\n            </div>\n        </div>\n\n        <table class="roadmap-table">\n            <thead>\n                <tr>\n                    <th><span class="txt-pt">Marco / Funcionalidade</span><span class="txt-en" style="display:none;">Milestone / Feature</span></th>\n                    <th><span class="txt-pt">Previsão</span><span class="txt-en" style="display:none;">Target</span></th>\n                    <th><span class="txt-pt">Status</span><span class="txt-en" style="display:none;">Status</span></th>\n                    <th><span class="txt-pt">Fundamentação Técnica</span><span class="txt-en" style="display:none;">Technical Specification</span></th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr>\n                    <td><strong>Motor de Extração Offline & Calibração</strong></td>\n                    <td>v1.2 (Entregue)</td>\n                    <td><span class="status-badge status-done">Concluído</span></td>\n                    <td>Visão computacional (CLAHE, Deskew) e calibração multidimensional ($\\tau = 0.35$).</td>\n                </tr>\n                <tr>\n                    <td><strong>Protocolo SC3 (Árvore de Merkle SHA-256)</strong></td>\n                    <td>v1.2 (Entregue)</td>\n                    <td><span class="status-badge status-done">Concluído</span></td>\n                    <td>Cadeia de custódia pericial com exportação <code>.sc3</code> conforme Arts. 158-A a 158-F do CPP.</td>\n                </tr>\n                <tr>\n                    <td><strong>Assinatura Digital Ed25519 / ICP-Brasil</strong></td>\n                    <td>Q4 2026</td>\n                    <td><span class="status-badge status-prog">Em Progresso</span></td>\n                    <td>Assinatura assimétrica de curvas elípticas sobre o Merkle Root com fé pública digital.</td>\n                </tr>\n                <tr>\n                    <td><strong>Detector de Bordas YOLOv8-Nano On-Device</strong></td>\n                    <td>Q4 2026</td>\n                    <td><span class="status-badge status-prog">Em Progresso</span></td>\n                    <td>Segmentação em tempo real no visor da câmera antes do disparo fotográfico.</td>\n                </tr>\n                <tr>\n                    <td><strong>RAG Jurídico Offline do Dec. 6.514/2008</strong></td>\n                    <td>Q1 2027</td>\n                    <td><span class="status-badge status-plan">Planejado</span></td>\n                    <td>Base vetorial SQLite embarcada correlacionando fatos descritos a tipos infracionais.</td>\n                </tr>\n                <tr>\n                    <td><strong>Sincronização Mesh P2P (Wi-Fi Direct)</strong></td>\n                    <td>Q1 2027</td>\n                    <td><span class="status-badge status-plan">Planejado</span></td>\n                    <td>Troca descentralizada de dossiês entre viaturas em campo sem infraestrutura central.</td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n\n    <!-- Footer -->\n    <footer>\n        <p>\n            <strong>SC3 DocAudit</strong> &bull; <a href="https://amazoniahack.co/" target="_blank">AmazoniaHack 4.0</a> &bull; <a href="https://github.com/Raoni1984/amazoniahackathon_s3c_docaudit" target="_blank">GitHub Repository</a> &bull; <a href="https://opensource.guide/" target="_blank">Open Source Guide</a>\n        </p>\n        <p style="font-size:12px; color: var(--text-subtle); margin-top: 6px;">\n            Licença Apache 2.0 &bull; Em conformidade estrita com os Arts. 158-A a 158-F do Código de Processo Penal Brasileiro.\n        </p>\n    </footer>\n\n</div>\n\n<script>\n    // Language Toggle Mechanism\n    let currentLang = \'pt\';\n    function toggleLanguage() {\n        currentLang = currentLang === \'pt\' ? \'en\' : \'pt\';\n        const isPt = currentLang === \'pt\';\n        \n        document.querySelectorAll(\'.txt-pt\').forEach(el => el.style.display = isPt ? \'\' : \'none\');\n        document.querySelectorAll(\'.txt-en\').forEach(el => el.style.display = isPt ? \'none\' : \'\');\n        \n        document.getElementById(\'langBtn\').textContent = isPt ? \'🌐 EN (English)\' : \'🌐 PT (Português)\';\n    }\n\n    // Confidence Simulator Logic\n    function runSim() {\n        const ocr = parseFloat(document.getElementById(\'sim_ocr\').value) / 100;\n        const syn = parseFloat(document.getElementById(\'sim_syn\').value) / 100;\n        const spa = parseFloat(document.getElementById(\'sim_spa\').value) / 100;\n\n        document.getElementById(\'val_ocr\').textContent = ocr.toFixed(2);\n        document.getElementById(\'val_syn\').textContent = syn.toFixed(2);\n        document.getElementById(\'val_spa\').textContent = spa.toFixed(2);\n\n        const score = Math.min(1.0, Math.max(0.0, (0.45 * ocr) + (0.35 * syn) + (0.20 * spa)));\n        document.getElementById(\'res_score\').textContent = score.toFixed(3);\n\n        const tag = document.getElementById(\'res_tag\');\n        if (score >= 0.35) {\n            tag.className = \'status-badge status-done\';\n            tag.textContent = currentLang === \'pt\' ? \'EXTRAÇÃO CONFIÁVEL\' : \'CONFIDENT EXTRACTION\';\n        } else {\n            tag.className = \'status-badge status-plan\';\n            tag.style.background = \'var(--danger-bg)\';\n            tag.style.color = \'var(--danger)\';\n            tag.textContent = currentLang === \'pt\' ? \'ABORTADO: SCORE < 0.35 (ATRIBUÍDO NULL)\' : \'ABORTED: SCORE < 0.35 (SET NULL)\';\n        }\n    }\n\n    // Cryptographic Merkle Calculation (SHA-256 via Web Crypto API)\n    async function sha256(str) {\n        const buffer = new TextEncoder().encode(str);\n        const digest = await crypto.subtle.digest(\'SHA-256\', buffer);\n        return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, \'0\')).join(\'\');\n    }\n\n    async function computeMerkle() {\n        const l1 = document.getElementById(\'m_leaf1\').value || \' \';\n        const l2 = document.getElementById(\'m_leaf2\').value || \' \';\n        const l3 = document.getElementById(\'m_leaf3\').value || \' \';\n        const l4 = document.getElementById(\'m_leaf4\').value || \' \';\n\n        const h1 = await sha256(l1);\n        const h2 = await sha256(l2);\n        const h3 = await sha256(l3);\n        const h4 = await sha256(l4);\n\n        const h12 = await sha256(h1 + h2);\n        const h34 = await sha256(h3 + h4);\n        const root = await sha256(h12 + h34);\n\n        document.getElementById(\'m_root\').textContent = root;\n    }\n\n    window.addEventListener(\'DOMContentLoaded\', () => {\n        runSim();\n        computeMerkle();\n    });\n</script>\n\n</body>\n</html>\n'
